from __future__ import annotations
import argparse

def build_parser() -> argparse.ArgumentParser:
    p=argparse.ArgumentParser()
    p.add_argument('--input-dir', required=True); p.add_argument('--known-state-csv', required=True); p.add_argument('--species-index', '--species-idx', dest='species_index', type=int, required=True); p.add_argument('--experiment-name', required=True)
    p.add_argument('--biology-label', choices=['detailed','trait'], default='detailed'); p.add_argument('--environment-state', choices=['dynamic-known','frozen-initial'], default='dynamic-known'); p.add_argument('--known-state-interpolation', choices=['linear','log-linear'], default='linear'); p.add_argument('--known-state-log-floor', type=float, default=1e-30)
    p.add_argument('--n-time', type=int, default=128); p.add_argument('--n-eval', type=int, default=60); p.add_argument('--n-steps', type=int, required=True); p.add_argument('--lr', type=float, default=3e-4); p.add_argument('--lr-min', type=float, default=1e-6)
    p.add_argument('--state-parameterization', choices=['log-u'], default='log-u'); p.add_argument('--state-scale-eps', type=float, default=1e-30); p.add_argument('--residual-form', choices=['scaled'], default='scaled'); p.add_argument('--boundary-loss-form', choices=['relative'], default='relative')
    p.add_argument('--lambda-pde', type=float, default=1.0); p.add_argument('--lambda-ic', type=float, default=1.0); p.add_argument('--lambda-bc', type=float, default=1.0); p.add_argument('--lambda-timestep', type=float, default=0.0)
    p.add_argument('--collocation-strategy', choices=['uniform'], default='uniform'); p.add_argument('--time-sampling', choices=['stratified'], default='stratified')
    p.add_argument('--causal-loss', choices=['expert'], default='expert'); p.add_argument('--causal-n-chunks', type=int, default=32); p.add_argument('--causal-epsilon', type=float, default=1.0); p.add_argument('--causal-curriculum', choices=['linear'], default='linear'); p.add_argument('--causal-start-fraction', type=float, default=0.05); p.add_argument('--causal-ramp-steps', type=int, default=1500); p.add_argument('--causal-step-fractions', default='0.05,0.10,0.20,0.40,0.70,1.0')
    p.add_argument('--loss-weighting', choices=['expert-grad-norm'], default='expert-grad-norm'); p.add_argument('--expert-weight-update-every', type=int, default=1000); p.add_argument('--expert-weight-alpha', type=float, default=0.7); p.add_argument('--expert-weight-batch', choices=['fixed'], default='fixed'); p.add_argument('--weight-min', type=float, default=1e-3); p.add_argument('--weight-max', type=float, default=1e3)
    p.add_argument('--model-arch', choices=['fourier'], default='fourier'); p.add_argument('--fourier-num-features', type=int, default=16); p.add_argument('--fourier-scale', type=float, default=1.0); p.add_argument('--fourier-include-raw-input', action='store_true', default=True); p.add_argument('--fourier-seed', type=int, default=123); p.add_argument('--weight-factorization', choices=['rwf'], default='rwf'); p.add_argument('--rwf-mu', type=float, default=1.0); p.add_argument('--rwf-sigma', type=float, default=0.1); p.add_argument('--rwf-apply-to', choices=['all'], default='all'); p.add_argument('--rwf-base-init', choices=['xavier_uniform'], default='xavier_uniform'); p.add_argument('--hidden-width', type=int, default=384); p.add_argument('--hidden-layers', type=int, default=5); p.add_argument('--lr-scheduler', choices=['cosine'], default='cosine'); p.add_argument('--seed', type=int, default=123); p.add_argument('--device', default='cpu'); p.add_argument('--hpc', action='store_true'); p.add_argument('--start-step', type=int, default=0)
    return p
